//! Byte parity with PyYAML's block-style dump.
//!
//! `tests/fixtures/pyyaml_corpus.json` is generated by running the real PyYAML
//! (`xtask/scripts/capture_pyyaml_corpus.py`) over an adversarial corpus of
//! scalars and documents. This test holds `xpst_config::pyyaml::dump` to it
//! byte for byte, because the config write path (`config export`, `config set`,
//! `config import`, `config fix`) produces a file the Python engine also writes
//! and a user is expected to read and diff.
//!
//! Regenerate the fixture with:
//!
//! ```text
//! <venv>/bin/python xtask/scripts/capture_pyyaml_corpus.py
//! ```

use xpst_config::pyyaml;
use xpst_config::{NonFinite, Value};

const FIXTURE: &str = include_str!("fixtures/pyyaml_corpus.json");

/// The corpus size. A loop over an emptied array asserts nothing, so the count
/// is pinned here as well as in the capture script.
const EXPECTED_ROWS: usize = 94;

/// Decode the capture script's markers for the two values JSON cannot carry.
///
/// `json.dumps` writes `Infinity`/`NaN` (invalid JSON) for a non-finite float
/// and raises for a date, so the script records them as `{"$non-finite": ...}`
/// and `{"$timestamp": ...}`. Everything else is a plain JSON value.
fn decode(value: &Value) -> Value {
    match value {
        Value::Mapping(map) => {
            if map.len() == 1 {
                if let Some(kind) = map.get("$non-finite").and_then(Value::as_str) {
                    return Value::NonFinite(match kind {
                        "inf" => NonFinite::Infinity,
                        "-inf" => NonFinite::NegInfinity,
                        "nan" => NonFinite::Nan,
                        other => panic!("unknown non-finite marker {other:?}"),
                    });
                }
                if let Some(text) = map.get("$timestamp").and_then(Value::as_str) {
                    return Value::Timestamp(text.to_string());
                }
            }
            let mut decoded = xpst_config::Mapping::new();
            for (key, item) in map {
                decoded.insert(key.clone(), decode(item));
            }
            Value::Mapping(decoded)
        }
        Value::Sequence(items) => Value::Sequence(items.iter().map(decode).collect()),
        other => other.clone(),
    }
}

#[test]
fn every_captured_row_renders_byte_identically() {
    // Parsed into `xpst_config::Value`, not `serde_json::Value`: the latter is a
    // BTreeMap and would sort each document's keys, so the corpus could not
    // pin key order at all.
    let document: Value = serde_json::from_str(FIXTURE).expect("fixture is JSON");
    let rows = document
        .get("rows")
        .and_then(Value::as_sequence)
        .expect("rows array");
    assert_eq!(
        rows.len(),
        EXPECTED_ROWS,
        "the corpus holds {} rows, not {EXPECTED_ROWS}: the capture wrote an empty or partial \
         collection",
        rows.len()
    );
    assert_eq!(
        document
            .get("row_count")
            .and_then(Value::as_u64)
            .unwrap_or(0) as usize,
        EXPECTED_ROWS,
        "row_count disagrees with the checked-in rows"
    );

    let mut failures = Vec::new();
    for row in rows {
        let value = decode(row.get("value").expect("row has a value"));
        let expected = row
            .get("yaml")
            .and_then(Value::as_str)
            .expect("yaml is text");
        let actual = pyyaml::dump(&value);
        if actual != expected {
            failures.push(format!(
                "value {:?}\n  expected {:?}\n  actual   {:?}",
                value, expected, actual
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} rows differ from PyYAML:\n{}",
        failures.len(),
        rows.len(),
        failures.join("\n")
    );
}

#[test]
fn the_emitter_is_not_vacuous() {
    // A guard on the guard: the corpus must contain rows that exercise each
    // quoting style, or a regression that quotes everything (or nothing) would
    // still pass.
    let document: Value = serde_json::from_str(FIXTURE).expect("fixture is JSON");
    let rows = document
        .get("rows")
        .and_then(Value::as_sequence)
        .expect("rows array");
    let rendered: Vec<&str> = rows
        .iter()
        .filter_map(|row| row.get("yaml").and_then(Value::as_str))
        .collect();
    assert!(
        rendered.iter().any(|text| text.contains('\'')),
        "no row is single-quoted"
    );
    assert!(
        rendered.iter().any(|text| text.contains('"')),
        "no row is double-quoted"
    );
    assert!(
        rendered.iter().any(|text| text.contains("\n  ")),
        "no row folds or indents"
    );
}
